const data = $input.first().json.body || $input.first().json;
const weight = parseFloat(data.weight);
const date = data.date;
const userId = data.user_id || 1;

if (!weight || isNaN(weight)) {
  throw new Error('Invalid weight value');
}

return [{ json: { user_id: userId, date, weight, body_fat: data.body_fat, processed_at: new Date().toISOString() } }];

const stats = $input.first().json;
const prevWeight = stats?.data?.latest?.weight;
const currentWeight = $('Validate & Parse Data').first().json.weight;
const weekAvg = stats?.data?.weekAvg?.avg_weight;

const change = prevWeight ? (currentWeight - prevWeight).toFixed(2) : 0;
const trend = change < 0 ? 'LOSING' : change > 0 ? 'GAINING' : 'MAINTAINING';

return [{
  json: {
    ...$('Validate & Parse Data').first().json,
    weight_change: parseFloat(change),
    trend,
    weekly_avg: weekAvg ? parseFloat(weekAvg.toFixed(2)) : currentWeight,
    summary: `Weight logged: ${currentWeight}kg (${change > 0 ? '+' : ''}${change}kg). Trend: ${trend}. Weekly avg: ${weekAvg ? weekAvg.toFixed(1) : 'N/A'}kg`
  }
}];
